// twoLang is a failure message in Chinese and English; the web UI shows the learner's language.
type twoLang struct{ zh, en string }

// say formats both languages with the same arguments, so the two formats must use them in the same order
// (use explicit indexes like %[2]d if a language needs another order).
func say(zh, en string, a ...interface{}) twoLang {
	f := fmt.Sprintf // through a variable, so vet doesn't take say for a printf wrapper with one format
	return twoLang{f(zh, a...), f(en, a...)}
}

// fail reports a failure the web UI understands, then stops the test.
// code picks the targeted hint (byCode in web/js/dojos/<id>.js); msg is shown to the learner as is,
// in their language:  fail(t, "wrong_total", say("总和应该是 %d。", "The sum should be %d.", want))
func fail(t *testing.T, code string, msg twoLang, extra ...map[string]interface{}) {
	t.Helper()
	m := map[string]interface{}{"code": code, "msg": msg.zh, "msg_en": msg.en}
	for _, e := range extra {
		for k, v := range e {
			m[k] = v
		}
	}
	b, _ := json.Marshal(m)
	t.Log("DOJO_FAIL " + string(b))
	t.FailNow()
}

func sum(c []int) int {
	s := 0
	for _, v := range c {
		s += v
	}
	return s
}
